-- ------------------------------------------------------------------------
-- 0004_user_directory.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- User Master → user_directory: the engineer/manager directory (names +
-- reporting hierarchy) that drives who-sees-what. Separate from auth logins
-- (profiles): a person is scoped by matching their login email to a directory
-- row, then by the RM/RGM tree (by name). Admins (profiles.role='admin') see all.
-- ===========================================================================

create table if not exists public.user_directory (
  id                 bigint generated always as identity primary key,
  name               text not null,               -- User Name (matches "Call Allocated To")
  email              text default '',
  gmail              text default '',
  designation        text default '',
  reporting_manager  text default '',             -- RM name
  regional_manager   text default '',             -- RGM name
  region             text default '',
  validity           boolean not null default true,
  extra              jsonb not null default '{}'
);
create index if not exists user_directory_email_idx on public.user_directory (lower(email));
create index if not exists user_directory_gmail_idx on public.user_directory (lower(gmail));
create index if not exists user_directory_name_idx  on public.user_directory (lower(name));

alter table public.user_directory enable row level security;
drop policy if exists ud_read on public.user_directory;
create policy ud_read on public.user_directory for select using (auth.role() = 'authenticated');
drop policy if exists ud_admin_write on public.user_directory;
create policy ud_admin_write on public.user_directory for all using (public.is_admin()) with check (public.is_admin());

-- The signed-in user's directory name (by login email or gmail).
create or replace function public.my_dir_name()
returns text language sql stable security definer set search_path = public as $$
  select name from public.user_directory
   where lower(email) = lower(auth.email()) or lower(gmail) = lower(auth.email())
   limit 1;
$$;

-- Names the current user may see: their own + everyone in their reporting
-- sub-tree (recursive over reporting_manager / regional_manager, by name).
create or replace function public.visible_engineer_names()
returns setof text language sql stable security definer set search_path = public as $$
  with recursive me as (
    select name from public.user_directory
     where lower(email) = lower(auth.email()) or lower(gmail) = lower(auth.email())
  ),
  tree as (
    select d.name from public.user_directory d where d.name in (select name from me)
    union
    select c.name from public.user_directory c
      join tree t
        on lower(c.reporting_manager) = lower(t.name)
        or lower(c.regional_manager)  = lower(t.name)
  )
  select name from tree where coalesce(name,'') <> '';
$$;

-- can_see_call() already uses visible_engineer_names(), so call scoping now
-- follows the directory automatically (admins still bypass via is_admin()).

-- ------------------------------------------------------------------------
-- 0029_engineer_address.sql
-- ------------------------------------------------------------------------

-- ===========================================================================
-- An engineer's delivery address, on the User Master.
--
-- The Declaration form that travels with the parcel ("TO WHOMSOEVER IT MAY
-- CONCERN") addresses it to the engineer. The User Master is where that
-- belongs — its sheet already has ADDRESS / CITY / STATE / Contact No columns,
-- and the User Master screen already showed City, State and Contact — but
-- user_directory never carried them, so on Supabase those columns were blank
-- and the form had nothing to read.
--
-- The four join the directory row, beside the name every other module already
-- refers to an engineer by, so one address serves every future document.
--
-- WHO MAY WRITE THEM is a separate migration (0030_engineer_address_write),
-- because its policy calls has_perm(), which the RBAC module defines and which
-- applies after this one. The columns themselves belong here, with the rest of
-- the User Master.
-- ===========================================================================

alter table public.user_directory
  add column if not exists address text default '',
  add column if not exists city    text default '',
  add column if not exists state   text default '',
  add column if not exists phone   text default '';

-- A directory imported before these were columns put them in `extra` (the
-- in-app importer kept every unmapped sheet column there). Lift them across,
-- so an existing deployment does not have to re-import to address a parcel.
--
-- The write guard is dropped first when it exists: this is a data migration,
-- not somebody editing the directory, and auth.uid() is NULL in the SQL
-- editor, so the guard would refuse it. It is put back below — and on a first
-- run there is nothing to put back, since 0030 has not created it yet.
drop trigger if exists user_directory_address_guard on public.user_directory;

update public.user_directory u
   set address = coalesce(nullif(btrim(u.address), ''),
                          nullif(btrim(u.extra ->> 'ADDRESS'), ''),
                          nullif(btrim(u.extra ->> 'Address'), ''), ''),
       city    = coalesce(nullif(btrim(u.city), ''),
                          nullif(btrim(u.extra ->> 'CITY'), ''),
                          nullif(btrim(u.extra ->> 'City'), ''), ''),
       state   = coalesce(nullif(btrim(u.state), ''),
                          nullif(btrim(u.extra ->> 'STATE'), ''),
                          nullif(btrim(u.extra ->> 'State'), ''), ''),
       phone   = coalesce(nullif(btrim(u.phone), ''),
                          nullif(btrim(u.extra ->> 'Contact  No'), ''),
                          nullif(btrim(u.extra ->> 'Contact No'), ''),
                          nullif(btrim(u.extra ->> 'Contact'), ''), '')
 where u.extra <> '{}'::jsonb;

do $$
begin
  if to_regprocedure('public.user_directory_address_guard()') is not null then
    create trigger user_directory_address_guard
      before update on public.user_directory
      for each row execute function public.user_directory_address_guard();
  end if;
end $$;

commit;
